<?php
require_once __DIR__.'/../includes/auth.php'; require_role('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$status=$_POST['status'];$pdo->prepare("UPDATE maintenance_requests SET status=?,admin_remarks=? WHERE id=?")->execute([$status,trim($_POST['remarks']),$id]);$s=$pdo->prepare("SELECT equipment_id,reported_by FROM maintenance_requests WHERE id=?");$s->execute([$id]);$r=$s->fetch();if($r){$condition=$status==='Repaired'||$status==='Closed'?'Good':'Under Maintenance';$pdo->prepare("UPDATE equipment SET condition_status=? WHERE id=?")->execute([$condition,$r['equipment_id']]);notify($pdo,(int)$r['reported_by'],'Maintenance report #'.$id.' is now '.$status.'.');}flash('Maintenance record updated.');redirect('maintenance.php');}
$rows=$pdo->query("SELECT m.*,e.name equipment_name,e.equipment_code,u.name reporter FROM maintenance_requests m JOIN equipment e ON e.id=m.equipment_id JOIN users u ON u.id=m.reported_by ORDER BY m.created_at DESC")->fetchAll();page_header('Maintenance Management','admin');?>
<div class="panel"><h2 class="section-title">Equipment issue reports</h2><div class="table-responsive"><table class="table"><thead><tr><th>Equipment</th><th>Reported by</th><th>Issue</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['equipment_name'])?><br><small class="muted"><?=e($r['equipment_code'])?></small></td><td><?=e($r['reporter'])?></td><td><?=e($r['issue_type'])?> — <?=e($r['description'])?></td><td><?=status_badge($r['status'])?></td><td><form method="post" class="d-flex gap-2"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select class="form-select" name="status"><?php foreach(['Reported','Under Review','In Progress','Repaired','Closed'] as $st):?><option <?=$r['status']===$st?'selected':''?>><?=$st?></option><?php endforeach?></select><input class="form-control" name="remarks" placeholder="Admin remarks" value="<?=e($r['admin_remarks'])?>"><button class="btn btn-primary">Save</button></form></td></tr><?php endforeach?></tbody></table></div></div><?php page_footer();?>
